    "summary": "本来面目是六祖惠能为惠明上座直指的禅宗核心概念。“不思善不思恶，正与么时，那个是明上座本来面目？”——善恶念头不起的当下，那个能知能觉的，就是本来面目。它不是生灭法，不在时空之中——“本来面目没处藏，世界坏时渠不朽”。无门慧开评曰“譬如新荔支剥了壳，去了核送在尔口里，只要尔咽一咽”——六祖老婆心切，几乎替你嚼碎了。本来面目即自性、即佛性、即真心，只是从不同角度命名。",
