    "title": "当下",
    "category": "禅法",
    "summary": "当下，禅门时间观之核心：过去已灭、未来未至、现在不住，三际觅心了不可得；而觉悟不在他生来世，只在此刻当念。云门以日日是好日显之——不拣择前后，十五日以前不问、十五日以后不道，今日此刻即是全体显现。悟前求道似欠一物，悟后当下圆满无缺；生死涅槃之大事，解决的时机永远是现在这一念。所谓放下过去、不迎未来、不住现在，念念即是。",
