    "summary": "坐脱立亡有实到与似到之分。参禅悟道、修持得证道果者临终坐脱立亡为实到；不曾悟道仅有静定之功者亦能坐脱立亡为似到。不悟道虽能坐脱立亡，只在识神阴界，不出轮回生死。 在禅宗心法中，此概念直指行者自心本具之真如实相，揭示迷悟不二、染净同体之甚深义理。行者若能透达此理，便能于纷繁复杂之世间万相中洞见空性本质，不住两边，圆融无碍。 宗门大德开示，知此名相非为空谈，贵在当人反躬自省，照见本来无一物之自性，体用一如。",
