    "summary": "棒喝者，禅宗接引学人之独特施设。棒始于德山宣鉴，喝始于临济义玄，合称“德山棒、临济喝”。学人拟议思量之际，师家以棒打或大喝截断其意识分别，令于言语道断处瞥见本来。 在禅宗心法中，此概念直指行者自心本具之真如实相，揭示迷悟不二、染净同体之甚深义理。行者若能透达此理，便能于纷繁复杂之世间万相中洞见空性本质，不住两边，圆融无碍。 宗门大德开示，知此名相非为空谈，贵在当人反躬自省，照见本来无一物之自性，体用一如。",
