    "summary": "大机大用，禅宗宗师接引学人之最高施设。机者应机之便，用者妙用之施。不拘常格，纵横自在，皆从般若妙智中流出。 在禅宗心法中，此概念直指行者自心本具之真如实相，揭示迷悟不二、染净同体之甚深义理。行者若能透达此理，便能于纷繁复杂之世间万相中洞见空性本质，不住两边，圆融无碍。 宗门大德开示，知此名相非为空谈，贵在当人反躬自省，照见本来无一物之自性，体用一如。",
