    "summary": "一切众生身中本具之无漏清净佛性与真如法身。如来藏自性明亮清净、本来不生不灭，虽为贪瞋痴烦恼客尘妄衣所缠覆，而自性本体皎洁无损。佛教如来藏与外道‘神我’之根本分野，在于如来藏即是诸法空、无相、无愿、无自性之真如实相，离诸断常分别，为禅宗‘直指人心、见性成佛’之究竟理论源流。",
    "etymology": "源出《入楞伽经》、《胜鬘经》，北宋法护、惟净译《大乘宝要义论》卷九专章辨明如来藏本来清净非外道神我。",
    "quotes": [
      "如来具三十二相在一切有情身中，如无价宝为弊垢衣之所缠覆……如来藏自性明亮清净、本来清净。",
      "佛说如来藏，即是开演空、无相、无愿、实际、法性，令诸有情断除神我计执。"
    ],
    "guidance": "体认如来藏切莫将其物化为内在藏匿之‘小灵魂’或神我实体。当于现前一念妄念息灭处，觉照能照能知之空寂灵明，即见本来清净之如来藏心。",
    "classicRef": "大乘宝要义论卷第九 · 楞伽辨如来藏",
